import { getLoggedUserProfile } from "@/services/auth";
import { redirect } from "next/navigation";

export default async function DashboardUtama() {
  const profile = await getLoggedUserProfile();

  if (!profile) redirect("/login");

  // Ambil nama ruangan dengan proteksi array/objek sesuai diskusi sebelumnya
  const namaRuangan = Array.isArray(profile.master_ruangan) 
    ? profile.master_ruangan[0]?.nama_ruangan 
    : profile.master_ruangan?.nama_ruangan || "Ruangan Belum Diatur";

  return (
    <div className="p-6 space-y-8">
      {/* Header Welcome */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Dashboard {profile.role}</h1>
          <p className="text-slate-500 text-sm">Selamat datang kembali, {profile.full_name || 'Petugas'}</p>
        </div>
        <div className="bg-blue-100 text-blue-700 px-4 py-2 rounded-lg font-semibold text-sm">
          📍 {namaRuangan}
        </div>
      </div>

      {/* STAT CARDS - Gaya WowDash */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Card 1: Total Input Hari Ini */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-4">
          <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center text-2xl">📝</div>
          <div>
            <p className="text-slate-500 text-xs font-medium uppercase tracking-wider">Pasien Hari Ini</p>
            <h3 className="text-2xl font-bold text-slate-800">24</h3>
          </div>
        </div>

        {/* Card 2: Indikator UC */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-4">
          <div className="w-12 h-12 bg-pink-50 rounded-xl flex items-center justify-center text-2xl">💉</div>
          <div>
            <p className="text-slate-500 text-xs font-medium uppercase tracking-wider">Total UC/CVL</p>
            <h3 className="text-2xl font-bold text-slate-800">12</h3>
          </div>
        </div>

        {/* Card 3: Alert HAIs */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-4">
          <div className="w-12 h-12 bg-orange-50 rounded-xl flex items-center justify-center text-2xl">⚠️</div>
          <div>
            <p className="text-slate-500 text-xs font-medium uppercase tracking-wider">Potensi HAIs</p>
            <h3 className="text-2xl font-bold text-slate-800 text-orange-600">0</h3>
          </div>
        </div>

        {/* Card 4: Status Sinkronisasi */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-4">
          <div className="w-12 h-12 bg-emerald-50 rounded-xl flex items-center justify-center text-2xl">✅</div>
          <div>
            <p className="text-slate-500 text-xs font-medium uppercase tracking-wider">Status Data</p>
            <h3 className="text-lg font-bold text-emerald-600">Tersinkron</h3>
          </div>
        </div>
      </div>

      {/* Konten Utama - Akses Cepat */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h2 className="text-lg font-bold text-slate-800 mb-4 text-center">Informasi Penting Unit {namaRuangan}</h2>
          <div className="h-40 flex flex-col items-center justify-center border-2 border-dashed border-slate-100 rounded-xl text-slate-400">
            <p>Belum ada pengumuman terbaru untuk RS Arun Lhokseumawe.</p>
          </div>
        </div>

        <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-2xl shadow-lg text-white">
          <h2 className="text-lg font-bold mb-2">Input Sekarang</h2>
          <p className="text-blue-100 text-sm mb-6">Mulai masukkan data surveilans pasien untuk hari ini agar laporan PPI akurat.</p>
          <a href="/dashboard/perawat/form" className="bg-white text-blue-700 px-6 py-3 rounded-xl font-bold text-sm block text-center shadow-md hover:bg-blue-50 transition-all">
            Buka Form Surveilans
          </a>
        </div>
      </div>
    </div>
  );
}